from functools import wraps


def count_calls(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)

    wrapper.calls = 0
    return wrapper


@count_calls
def add(left, right=1):
    """add two numbers"""
    return left + right


@count_calls
def negate(value):
    return -value


class CountCallsTest(unittest.TestCase):
    def test_metadata_is_preserved(self):
        self.assertEqual(add.__name__, "add")
        self.assertEqual(add.__doc__, "add two numbers")

    def test_arguments_and_result_are_forwarded(self):
        self.assertEqual(add(2, right=3), 5)
        self.assertEqual(add(2), 3)

    def test_calls_are_counted_per_function(self):
        add.calls = 0
        negate.calls = 0
        add(1)
        add(1)
        negate(1)
        self.assertEqual(add.calls, 2)
        self.assertEqual(negate.calls, 1)

    def test_wrapped_exposes_original(self):
        self.assertEqual(add.__wrapped__(2, 3), 5)


