import threading
import unittest
from concurrent.futures import ThreadPoolExecutor

STATE = threading.local()


def split_blocks(values, workers):
    return [values[index::workers] for index in range(workers)]


def block_sum(block):
    if not hasattr(STATE, "calls"):
        STATE.calls = 0
    STATE.calls += 1
    return sum(block), threading.current_thread().name, STATE.calls


def parallel_sum(values, workers):
    blocks = split_blocks(list(values), workers)
    with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="sum") as pool:
        futures = [pool.submit(block_sum, block) for block in blocks]
        results = [future.result(timeout=5.0) for future in futures]
    return sum(item[0] for item in results), results


class ParallelSumTest(unittest.TestCase):
    def test_split_blocks_is_balanced(self):
        blocks = split_blocks(list(range(10)), 3)
        self.assertEqual(len(blocks), 3)
        sizes = sorted(len(block) for block in blocks)
        self.assertLessEqual(sizes[-1] - sizes[0], 1)

    def test_total_matches_sum(self):
        total, _ = parallel_sum(range(1, 11), 3)
        self.assertEqual(total, 55)

    def test_thread_local_calls_increase_without_gaps(self):
        _, results = parallel_sum(range(1, 11), 3)
        seen = {}
        for _, name, calls in results:
            self.assertEqual(calls, seen.get(name, 0) + 1)
            seen[name] = calls

    def test_results_carry_thread_names_in_block_order(self):
        _, results = parallel_sum(range(1, 11), 2)
        self.assertEqual(len(results), 2)
        self.assertTrue(all(name for _, name, _ in results))


