import unittest


def read_lines(log, lines):
    log.append("open")
    try:
        for line in lines:
            yield line
    finally:
        log.append("close")


def consume_first(stream, log):
    try:
        return next(stream)
    finally:
        stream.close()


class ReadLinesTest(unittest.TestCase):
    def test_exhaustion_runs_cleanup_once(self):
