import logging
import unittest
from io import StringIO


class AppError(Exception):
    pass


class NotFound(AppError):
    pass


def make_logger():
    logger = logging.Logger("boundary")
    handler = logging.StreamHandler(StringIO())
    handler.setFormatter(logging.Formatter("%(levelname)s:%(message)s"))
    logger.addHandler(handler)
    logger.setLevel(logging.INFO)
    return logger, handler.stream


def load(repository, key):
    try:
        return repository[key]
    except KeyError as error:
        raise NotFound("missing " + key) from error


def handle(logger, repository, key):
    try:
        value = load(repository, key)
    except AppError as error:
        cause = type(error.__cause__).__name__ if error.__cause__ else ""
        logger.error("request failed: %s", type(error).__name__)
        return {"ok": False, "error": type(error).__name__, "cause": cause}
    return {"ok": True, "value": value}


class BoundaryTest(unittest.TestCase):
    def test_success_has_no_error_log(self):
        logger, stream = make_logger()
        result = handle(logger, {"7": "seven"}, "7")
        self.assertEqual(result, {"ok": True, "value": "seven"})
        self.assertEqual(stream.getvalue(), "")

    def test_missing_key_is_translated_and_logged_once(self):
        logger, stream = make_logger()
        result = handle(logger, {}, "7")
        self.assertFalse(result["ok"])
        self.assertEqual(result["error"], "NotFound")
        lines = stream.getvalue().splitlines()
        self.assertEqual(len(lines), 1)
        self.assertIn("NotFound", lines[0])

    def test_cause_is_preserved(self):
        logger, _ = make_logger()
        result = handle(logger, {}, "7")
        self.assertEqual(result["cause"], "KeyError")

    def test_programming_errors_are_not_swallowed(self):
        logger, _ = make_logger()
        with self.assertRaises(TypeError):
            handle(logger, None, "7")


if __name__ == "__main__":
    unittest.main()
